#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("NO_INPUT\n");
        return 0;
    }
    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1]) {
        printf("BAD_INPUT\n");
        return 0;
    }
    if (n < 1) {
        printf("OUT_OF_RANGE\n");
        return 0;
    }
    long long pascal_triangle[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= i; j++) {
            if (j == 0 || j == i) {
                pascal_triangle[i][j] = 1;
            } else {
                pascal_triangle[i][j] = pascal_triangle[i-1][j-1] + pascal_triangle[i-1][j];
            }
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            printf(" ");
        }
        for (int j = 0; j <= i; j++) {
            printf("%lld ", pascal_triangle[i][j]);
        }
        printf("\n");
    }
    return 0;
}
